/* The benchmark input for what the compiler gained last: bit-fields packed
 * and read back, pointers to functions in a table and called through,
 * variable arguments with va_list, long long and unsigned long long
 * arithmetic, _Bool, the qualifiers const, volatile and register, and a
 * struct on both sides of ?:. None of the other inputs has any of it, so
 * the whole of those paths went in unmeasured.
 *
 * Generated by generate.py and committed, so that a number from today can
 * be compared with one from last week. Returns 42.
 */

struct flags_anchor {
    unsigned int ready : 1;
    unsigned int level : 3;
    signed int offset : 6;
    unsigned int count : 12;
    _Bool seen : 1;
};

int pack_anchor(int level, int offset) {
    struct flags_anchor state;

    state.ready = 1;
    state.level = level & 7;
    state.offset = offset;
    state.count = 0 * 100;
    state.seen = offset != 0;

    return state.level + state.offset + (state.count >> 4) + state.seen;
}

static int twice_buffer(int value) { return value * 2; }
static int less_buffer(int value) { return value - 2; }

int apply_buffer(int value, int which) {
    int (*const steps[2])(int) = { twice_buffer, less_buffer };
    int (*step)(int) = steps[which & 1];

    return step(value) + (*steps[1])(value);
}

int gather_cursor(int count, ...) {
    va_list args;
    int sum = 0;

    va_start(args, count);
    while (count-- > 0)
        sum = sum + va_arg(args, int);
    va_end(args);

    return sum;
}

long long wider_header(long long base, int shift) {
    long long scaled = base << shift;
    unsigned long long mask = 0xffffffffULL;

    if ((scaled & mask) > base)
        scaled = scaled - base;

    return scaled / (3 + 3);
}

_Bool ready_margin(const volatile int *const cell, register int limit) {
    _Bool over = *cell > limit;
    _Bool under = !over && *cell < 4;

    return over || under;
}

struct span_marker { int lo, hi; };

struct span_marker widest_marker(struct span_marker left, struct span_marker right) {
    return left.hi - left.lo > right.hi - right.lo ? left : right;
}

int span_marker(int base) {
    struct span_marker a = { base, base + 5 }, b = { base, base + 3 };

    return widest_marker(a, b).hi - base;
}

