    total = total + (int) (wider_record1(700000LL, 1) % 97);
    { volatile int cell = 0; total = total + ready_result1(&cell, 0); }
    total = total + span_stride1(1);
    total = total + pack_bucket1(2, -1);
    total = total + apply_origin1(3, 3);
    total = total + gather_prefix1(3, 4, 5, 6);
    total = total + (int) (wider_window1(600000LL, 0) % 97);
    { volatile int cell = 18; total = total + ready_column1(&cell, 6); }
    total = total + span_credit1(0);
    total = total + pack_ledger1(1, -2);
    total = total + apply_sample1(2, 2);
    total = total + gather_signal1(3, 3, 4, 5);
    total = total + (int) (wider_target1(500000LL, 4) % 97);
    { volatile int cell = 15; total = total + ready_anchor2(&cell, 5); }
    total = total + span_buffer2(6);
    total = total + pack_cursor2(0, -3);
    total = total + apply_header2(1, 1);
